      case messages::Page::kOnCustomImageBackgroundsUpdated:
            return "Receive brave_new_tab_page::mojom::Page::OnCustomImageBackgroundsUpdated";
      case messages::Page::kOnSearchPromotionDisabled:
            return "Receive brave_new_tab_page::mojom::Page::OnSearchPromotionDisabled";
